function card(r, i, top){
  const el = document.createElement('div');
  el.className = 'card';
  el.style.animationDelay = Math.min(i * 24, 260) + 'ms';

  const isFile = r.kind === 'file';       // 「我的文件」：读者自己放进去的，没有链接，看全文就是它本身
  const titleHtml = isFile ? esc(r.title)
    : `<a href="${esc(r.link)}" target="_blank" rel="noopener">${esc(r.title)}</a>`;

  const tags = [];
  if (r.date) tags.push(`<span>${r.date}</span>`);
  if (r.kind === 'comic') tags.push(`<span class="tag comic">漫画</span>`);
  if (isFile) tags.push(`<span class="tag">我的文件</span>`);
  if (r.read_num != null) tags.push(`<span class="tag">${r.read_num} 阅读</span>`);
  if (r.hit_count > 1) tags.push(`<span class="tag">文中 ${r.hit_count} 段相关</span>`);
  const lvl = r.score >= 0.60 ? ' strong' : r.score >= 0.30 ? '' : ' weak';
  tags.push(`<span class="tag score${lvl}" title="语义 ${(r.vec_score*100).toFixed(0)} / 字面 ${(r.lex_score*100).toFixed(0)}">匹配 ${r.rel}%</span>`);

  // 漫画常常没有正文，摘要就是标题本身，显示出来等于重复一遍。有图就不摆这句废话。
  const 去掉重复标题 = (s) => {
    const a = s.text.replace(/<[^>]+>/g, '').replace(/\s/g, '');
    const b = (r.title || '').replace(/\s/g, '');
    return !(a && b && (a === b || (a.length < b.length + 6 && b.includes(a.slice(0, 12)))));
  };
  const snips = r.snippets.filter(s => !r.thumbs || 去掉重复标题(s)).map(s =>
    `<p class="snip">${s.heading ? `<span class="h">${esc(s.heading)}</span>` : ''}${highlight(s.text)}</p>`
  ).join('');

  // 漫画有图就铺一行缩略图，点开原文
  const thumbs = r.thumbs
    ? `<div class="thumbs">` + Array.from({length: r.thumbs}, (_, n) =>
        `<a href="${esc(r.link)}" target="_blank" rel="noopener">` +
        `<img loading="lazy" alt="" src="/api/thumb?id=${encodeURIComponent(r.id)}&n=${n}"></a>`
      ).join('') + `</div>`
    : '';

